import{_ as r,C as t,o,c as s,E as n,a2 as c}from"./chunks/framework.DyLyN3RJ.js";const v=JSON.parse('{"title":"Where Check Fields Come From: The Evidence Boundary of Multi-Agent Acceptance","description":"","frontmatter":{"title":"Where Check Fields Come From: The Evidence Boundary of Multi-Agent Acceptance","article_type":"engineering-insight","edition":"research-center","research_question":"检查字段的来源和语义范围如何影响独立验收？","research_question_en":"How do the origin and semantic coverage of check fields affect independent acceptance?","summary":"Isolated function probes distinguish storing a check verdict from performing verification. Acceptance interfaces need to expose who generated a field, which proposition it covers and what evidence remains missing.","sources":["https://arxiv.org/html/2611.08971v1","https://arxiv.org/html/2611.02581v1","https://github.com/CMME-Lab/SMILE"],"date":"2026-11-13","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261113-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-13-sig-20261113-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-11-13-sig-20261113-006.md","filePath":"en/industry/2026-11-13-sig-20261113-006.md","lastUpdated":1794573189000}'),d={name:"en/industry/2026-11-13-sig-20261113-006.md"};function l(p,e,h,u,m,f){const a=t("ArticleCover"),i=t("ArticleTableScroll");return o(),s("div",null,[n(a,{image:"/assets/covers/daily-2026-11-13-sig-20261113-006-cover.png",kicker:"Research",title:"Where Check Fields Come From: The Evidence Boundary of Multi-Agent Acceptance",summary:"Isolated function probes distinguish storing a check verdict from performing verification. Acceptance interfaces need to expose who generated a field, which proposition it covers and what evidence remains missing.",version:"2026-11-13",languageHref:"/zh/industry/2026-11-13-sig-20261113-006",languageLabel:"中文"}),n(i,{language:"en"}),e[0]||(e[0]=c(`<h1 id="where-check-fields-come-from-the-evidence-boundary-of-multi-agent-acceptance" tabindex="-1">Where Check Fields Come From: The Evidence Boundary of Multi-Agent Acceptance <a class="header-anchor" href="#where-check-fields-come-from-the-evidence-boundary-of-multi-agent-acceptance" aria-label="Permalink to &quot;Where Check Fields Come From: The Evidence Boundary of Multi-Agent Acceptance&quot;">​</a></h1><p>When a result object contains a pass verdict, did the system perform an independent check, or merely preserve its producer&#39;s judgment? A small input makes the distinction concrete: supply a normalizer with three pass fields and an unsupported assertion, and those fields survive. That is what the internal probe discussed here observed. It establishes a storage boundary, not that the complete system accepted a wrong result.</p><p>The article&#39;s proposition is narrow: before treating a check field as independent acceptance, inspect its origin and semantic coverage. Agreement among agents and the presence of a dedicated judge do not answer either question by themselves.</p><h2 id="a-check-can-record-a-claim-without-checking-it" tabindex="-1">A check can record a claim without checking it <a class="header-anchor" href="#a-check-can-record-a-claim-without-checking-it" aria-label="Permalink to &quot;A check can record a claim without checking it&quot;">​</a></h2><p>Three kinds of evidence are kept separate here. Experimental results in the papers are source-reported claims. Operations visible in pinned code are our source observations. Outputs from the synthetic inputs below are internal experimental evidence, without independent reproduction. The interface recommendations are interpretations of those materials, not a generally validated solution.</p><p>SMILE describes constrained consolidation: morphology, pathology and visual-question-answering specialists supply a frozen, image-aware judge. Its prompt requires source-specific criticism, restricts non-imaging diagnostic content and incorporates a limited set of visual attributes. This is more specific than an unconditional majority vote. Nevertheless, check fields generated by the judge still originate in that model&#39;s output. Storing them in an object does not confer the independence of a separate evidence chain. <a href="https://arxiv.org/html/2611.02581v1" target="_blank" rel="noreferrer">SMILE, §§3–4 and Supplement D</a></p><p>The pinned council code sends images and candidate outputs to a model and retains generated rule-check fields. The useful question is therefore whether a field represents a prompt constraint, a self-declaration, a deterministic predicate or acceptance reconciled against original evidence—not merely whether the field exists. <a href="https://raw.githubusercontent.com/CMME-Lab/SMILE/c81c22832b1b7de73a00d02d201fdd3f1f49e3eb/src/smile/council.py" target="_blank" rel="noreferrer">Pinned council implementation</a></p><h2 id="two-studies-two-different-evidence-problems" tabindex="-1">Two studies, two different evidence problems <a class="header-anchor" href="#two-studies-two-different-evidence-problems" aria-label="Permalink to &quot;Two studies, two different evidence problems&quot;">​</a></h2><p>PHANTOM-Bench compares private decisions, public decisions and decisions after peer information is revealed. Its authors report lower public than private accuracy for all nine evaluated models. One model falls from 0.770 to 0.292, a 47.8 percentage-point difference. These are controlled benchmark outcomes, not deployed-system failure rates. Public comments are supplied experimental stimuli rather than a live discussion generated by the four evaluated agents. <a href="https://arxiv.org/html/2611.08971v1" target="_blank" rel="noreferrer">PHANTOM-Bench, §§3–5 and Table 1</a></p><p>Its recovery measure also needs its denominator: it conditions on agent–scenario pairs that were private-correct and public-wrong. For one model, conditional recovery is 0.623, while overall accuracy drops from 0.598 in the public condition to 0.561 after peer decisions are supplied. Conditional recovery and overall improvement are different claims. Revealing decisions also adds task-relevant information, preventing the recovery result from isolating belief correction as a cause. <a href="https://arxiv.org/html/2611.08971v1" target="_blank" rel="noreferrer">PHANTOM-Bench, §5.1 and Appendix C</a></p><p>SMILE instead reports benefits from specialization and judge constraints against tested controls, while retaining failure examples: a correct minority finding can be ignored, and a finding absent from specialist evidence can remain missing after consolidation. The studies have no shared accuracy denominator and cannot rank the two systems. Their useful engineering comparison is narrower: recording opinions, consolidating them and accepting a result against an independent reference carry different evidentiary responsibilities. <a href="https://arxiv.org/html/2611.02581v1" target="_blank" rel="noreferrer">SMILE, ablations and Supplement C</a></p><h2 id="what-the-isolated-functions-actually-returned" tabindex="-1">What the isolated functions actually returned <a class="header-anchor" href="#what-the-isolated-functions-actually-returned" aria-label="Permalink to &quot;What the isolated functions actually returned&quot;">​</a></h2><p>The completed same-date Analysis extracted normalization and entity-presence functions from pinned source and executed them on synthetic inputs. Production reuses those completed results; it adds no experiment. No model, image or patient data was loaded in this probe.</p><p>The normalization inputs and outputs were as follows. The <a href="/joinwell52/assets/evidence/2026-11-13-sig-20261113-006/article-evidence.json">internal probe record</a> retains complete values, function line ranges, environment and source hashes.</p><table tabindex="0"><thead><tr><th>Synthetic input</th><th>Observed output</th><th>Supported interpretation</th></tr></thead><tbody><tr><td>Null</td><td>Failure defaults</td><td>Null has an explicit failure representation</td></tr><tr><td>Empty object</td><td>Missing fields added, rule values empty</td><td>A complete shape does not establish checked content</td></tr><tr><td>Three pass fields and an unsupported assertion</td><td>Pass fields and assertion preserved</td><td>This function stores supplied judgments rather than rechecking their content</td></tr></tbody></table><p>The second probe executed the entity-presence function. Because the inspected source tree lacked the original entity resource, it explicitly injected a controlled vocabulary containing only cyst and replaced text cleaning with an identity function. The three pre-normalized English inputs were a positive mention, a negated mention and no mention:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cyst present         -&gt; 1</span></span>
<span class="line"><span>no cyst present      -&gt; 1</span></span>
<span class="line"><span>normal examination   -&gt; 0</span></span></code></pre></div><p>The internal observation is that positive and negative mentions collide in this function under this vocabulary and cleaning substitution. This is not a clinical-score reproduction: the complete vocabulary, original cleaning and model performance were not measured. It supplies an exact counterexample to equating entity presence with affirmation. A presence bit does not automatically answer polarity. <a href="https://raw.githubusercontent.com/CMME-Lab/SMILE/c81c22832b1b7de73a00d02d201fdd3f1f49e3eb/src/smile/eval/clinical_efficacy.py" target="_blank" rel="noreferrer">Pinned entity-scoring implementation</a></p><p>The paper itself defines its clinical-entity metric around presence categories, excluding polarity and severity. It reports a first-dataset entity score of 0.82 against 0.69 and 0.73 for two comparators. Those remain author-reported values, cannot replace polarity accuracy and were not reproduced by this local probe. <a href="https://arxiv.org/html/2611.02581v1" target="_blank" rel="noreferrer">SMILE, Table 1 and Supplement B</a></p><h2 id="the-normalizer-may-be-doing-its-job" tabindex="-1">The normalizer may be doing its job <a class="header-anchor" href="#the-normalizer-may-be-doing-its-job" aria-label="Permalink to &quot;The normalizer may be doing its job&quot;">​</a></h2><p>The strongest alternative explanation is straightforward: a normalizer may be responsible only for representation. Preserving upstream fields can be correct, and interpreting images need not be its responsibility. The observation is therefore not a function-level vulnerability finding or evidence that the complete system lacks other verification. Moving from no check here to no check anywhere would exceed the evidence.</p><p>The controlled vocabulary and cleaning seam impose another boundary. They make one predicate executable while narrowing what its output means. Missing original resources constrain a complete rerun. The probe cannot estimate patient outcomes, full-scorer error rates or clinical safety. PHANTOM&#39;s text-content and belief-elicitation confounds likewise prevent a universal causal explanation for all specialist councils.</p><h2 id="acceptance-needs-a-source-and-a-semantic-scope" tabindex="-1">Acceptance needs a source and a semantic scope <a class="header-anchor" href="#acceptance-needs-a-source-and-a-semantic-scope" aria-label="Permalink to &quot;Acceptance needs a source and a semantic scope&quot;">​</a></h2><p>A practical interpretation for multi-agent acceptance interfaces is to expose who generated a verdict, its evidence basis and the proposition actually checked. If a judge generated a field itself, the record should preserve that origin. If a check covers entity presence alone, it should distinguish unchecked polarity, severity and omitted findings. Different field names and more models do not fill those gaps automatically.</p><p>This changes how performance metrics should be read. An entity-presence score answers the question in its definition; lexical similarity answers another; item-by-item reconciliation against original images and independent annotations has different responsibilities again. Before choosing an acceptance metric, state the proposition that needs confirmation and inspect whether the metric covers it. This is a design judgment supported by bounded observations, not a guarantee that a field scheme ensures correctness across tasks.</p><h2 id="what-these-observations-leave-unresolved" tabindex="-1">What these observations leave unresolved <a class="header-anchor" href="#what-these-observations-leave-unresolved" aria-label="Permalink to &quot;What these observations leave unresolved&quot;">​</a></h2><p>Both papers report preprint experiments; neither was independently rerun here. PHANTOM uses fixed four-agent groups, curated synthetic scenarios and three actions. Aggregate measures do not establish decision-level co-occurrence or a causal chain. SMILE&#39;s cohorts and tasks are limited and do not establish general clinical conclusions. Missing packaged prompt text and entity resources further constrain end-to-end reproduction.</p><p>The unresolved issue is therefore whether each check can be traced to corresponding original evidence, whether its coverage suffices for acceptance, and whether those properties withstand independent examination in real end-to-end runs. Another pass field alone does not answer that question. This article provides no clinical recommendation.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><ul><li><a href="https://arxiv.org/html/2611.08971v1" target="_blank" rel="noreferrer">PHANTOM-Bench, version 1</a>: author-origin research material for design, metric denominators and reported outcomes; not independent reproduction evidence.</li><li><a href="https://arxiv.org/html/2611.02581v1" target="_blank" rel="noreferrer">SMILE, version 1</a>: author-origin research material for architecture, prompt constraints, metric definitions, ablations and failure examples.</li><li><a href="https://raw.githubusercontent.com/CMME-Lab/SMILE/c81c22832b1b7de73a00d02d201fdd3f1f49e3eb/src/smile/council.py" target="_blank" rel="noreferrer">Pinned council code</a> and <a href="https://raw.githubusercontent.com/CMME-Lab/SMILE/c81c22832b1b7de73a00d02d201fdd3f1f49e3eb/src/smile/eval/clinical_efficacy.py" target="_blank" rel="noreferrer">pinned entity scorer</a>: revision <code>c81c22832b1b7de73a00d02d201fdd3f1f49e3eb</code>, supporting local implementation observations.</li><li><a href="/joinwell52/assets/evidence/2026-11-13-sig-20261113-006/article-evidence.json">Internal probe record</a>: synthetic input/output measurements executed on 13 November 2026, retaining dependency substitutions and unmeasured boundaries. Not independent evidence or a clinical-system reproduction.</li></ul><p>Publication is not validation; citation is not endorsement; peer review is not proof; self-reported results are not independent evidence; successful local implementation does not establish general validity.</p>`,31))])}const b=r(d,[["render",l]]);export{v as __pageData,b as default};
